    {
      "path": "src/store.ts",
      "content": "/**
 * File-backed store for the dsh-codevault reading archive (V2 object cards).
 *
 * Model split (see DESIGN.md V2):
 *  - library.jsonl keeps APPEND-ONLY EVENTS (one ReadingEntry per read), the
 *    single source of truth for replay/stats/tests.
 *  - Obsidian VIEWS project events onto OBJECT cards: every event whose
 *    objectKey() is equal maps to ONE card `notes/<noteFile>.md`, whose body is
 *    a header + reading timeline + merged takeaways + same-repo links.
 *
 * Layout (default root = `~/.dsh/data/dsh-codevault`, overridable via the
 * DSCODEVAULT_DATA_DIR env var — used by smoke tests / CI):
 *
 *   <root>/library.jsonl   events (append-only, atomic)
 *   <root>/notes/<f>.md    one card per reading OBJECT (derived, rebuilt)
 *   <root>/hub/<slug>.md   per-repo hub: one line per object card
 *   <root>/MOC.md          overview: repo list / object counts / recent cards
 *
 * The object card name is frozen on the object's FIRST event and stored in
 * every row's `noteFile`; later events of the same object reuse the same card.
 * Cards / hubs / MOC are derived views and always rebuilt from library.jsonl,
 * so they never drift.
 *
 * Concurrency (V1 note still holds): all I/O synchronous, atomic tmp+rename;
 * cross-process writers: last writer wins (documented, accepted).
 */

import { createHash, randomUUID } from 'node:crypto'
import {
  existsSync,
  mkdirSync,
  readFileSync,
  renameSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { join } from 'node:path'
import { dshHomePath } from '@deepseek-ai/dsh-home-paths'
import {
  EntryKind,
  MAX_LINKS,
  MAX_REVISIT,
  MIN_NOTE_BODY,
  ReadingEntry,
  ReadingSubject,
  cardFileName,
  clip,
  entryKindText,
  entryObjectKey,
  entryTitle,
  normalizeLinks,
  normalizeRevisit,
  objectKey,
  subjectLabel,
  subjectOfKey,
} from './domain.js'

export const DATA_DIR_ENV = 'DSCODEVAULT_DATA_DIR'

/**
 * Module-level root set from the plugin Config (`dataDir`) once apply() runs.
 * Resolution priority: configured root > DSCODEVAULT_DATA_DIR env > default.
 */
let configuredRoot: string | undefined

/** Apply the plugin Config's dataDir (empty/whitespace falls back to env/default). */
export function configureDataRoot(dataDir: string | undefined): void {
  configuredRoot = dataDir?.trim() ? dataDir.trim() : undefined
}

/** Resolve the plugin data root. Lazily evaluated so tests can set the env. */
export function dataRoot(): string {
  if (configuredRoot) return configuredRoot
  const override = process.env[DATA_DIR_ENV]
  return override ? override : dshHomePath('data', 'dsh-codevault')
}

export function ensureStore(): string {
  const root = dataRoot()
  mkdirSync(join(root, 'notes'), { recursive: true })
  mkdirSync(join(root, 'hub'), { recursive: true })
  return root
}

function libraryFile(root: string): string {
  return join(root, 'library.jsonl')
}

/** Atomically replace `file` with `content` (same-dir temp + rename). */
function atomicWrite(file: string, content: string): void {
  const tmp = `${file}.tmp-${randomUUID()}`
  try {
    writeFileSync(tmp, content, 'utf8')
    renameSync(tmp, file)
  } finally {
    if (existsSync(tmp)) rmSync(tmp, { force: true })
  }
}

/** Read every event row on disk (tolerant of missing/corrupt lines). */
export function readEntries(): ReadingEntry[] {
  const file = libraryFile(dataRoot())
  if (!existsSync(file)) return []
  const raw = readFileSync(file, 'utf8')
  const entries: ReadingEntry[] = []
  for (const line of raw.split(/\r?\n/u)) {
    const trimmed = line.trim()
    if (!trimmed) continue
    try {
      const parsed = JSON.parse(trimmed) as ReadingEntry
      // Legacy rows (pre-links / pre-revisit) get empty arrays at read time.
      entries.push({
        ...parsed,
        links: Array.isArray(parsed.links) ? parsed.links : [],
        revisit: Array.isArray(parsed.revisit) ? parsed.revisit : [],
      })
    } catch (error) {
      console.warn('[dsh-codevault] skipping unparsable library line:', String(error))
    }
  }
  return entries
}

// ---------------------------------------------------------------------------
// Object grouping
// ---------------------------------------------------------------------------

/** All events grouped by objectKey (insertion order preserved per object). */
export function groupByObject(entries: readonly ReadingEntry[]): Map<string, ReadingEntry[]> {
  const map = new Map<string, ReadingEntry[]>()
  for (const e of entries) {
    const key = entryObjectKey(e)
    const arr = map.get(key) ?? []
    arr.push(e)
    map.set(key, arr)
  }
  return map
}

/** Earliest event of an object — the anchor whose title names the card. */
function anchorOf(events: ReadingEntry[]): ReadingEntry {
  return [...events].sort((a, b) => a.readAt.localeCompare(b.readAt))[0] ?? events[0]!
}

/** Display title of an object card (anchor's title, else coordinate title). */
export function objectTitle(events: ReadingEntry[]): string {
  return entryTitle(anchorOf(events))
}

/** Newest event of an object (for summaries/labels). */
function newestOf(events: ReadingEntry[]): ReadingEntry {
  return [...events].sort((a, b) => b.readAt.localeCompare(a.readAt))[0] ?? events[0]!
}

// ---------------------------------------------------------------------------
// Writes
// ---------------------------------------------------------------------------

/**
 * Persist one new event: append the library row, then rebuild the object card,
 * its repo hub, and the MOC.
 */
export function commitEntry(entry: ReadingEntry): { notePath: string; hubPath: string; mocPath: string } {
  const root = ensureStore()
  const rows = readEntries()
  const key = entryObjectKey(entry)
  const siblings = rows.filter((e) => entryObjectKey(e) === key)
  const noteFile = objectFileName([...siblings, entry], rows)
  const stored: ReadingEntry = { ...entry, noteFile }
  atomicWrite(libraryFile(root), [...rows, stored].map((e) => JSON.stringify(e)).join('\n') + '\n')
  const notePath = writeObjectCard(key)
  const hubPath = refreshHub(stored.subject.repo)
  const mocPath = refreshMOC()
  return { notePath, hubPath, mocPath }
}

/** File name (no .md) of an object card; frozen on first event, reused after. */
export function objectFileName(events: ReadingEntry[], allRows: readonly ReadingEntry[]): string {
  const existing = events.find((e) => e.noteFile)
  if (existing?.noteFile) return existing.noteFile
  const used = new Set(allRows.map((e) => e.noteFile).filter((f): f is string => Boolean(f)))
  const base = cardFileName(objectTitle(events))
  let candidate = base
  let i = 2
  while (used.has(candidate)) {
    candidate = `${base}-${i}`
    i += 1
  }
  return candidate
}

/**
 * Promote one event (a quick capture) into a deep-reading note IN PLACE: the
 * same row gains bodyMarkdown/takeaway (+ context if missing), kind flips to
 * 'note'; the object card is rebuilt in the SAME file (never renamed). This is
 * the archive's "quick first, deepen later" revision path.
 */
export function expandEntry(
  id: string,
  patch: { context?: string; bodyMarkdown: string; takeaway: readonly string[]; revisit?: readonly unknown[] },
): ReadingEntry {
  const root = ensureStore()
  const file = libraryFile(root)
  if (!existsSync(file)) throw new Error('档案为空，找不到要升级的记录')
  const rows = readEntries()
  const target = rows.find((e) => e.id === id)
  if (!target) throw new Error(`档案里没有 id=${id} 的记录`)
  if (target.bodyMarkdown) throw new Error(`id=${id} 已经是深读笔记（有正文），如需改写请删后重建`)

  const body = patch.bodyMarkdown.trim()
  if ([...body].length < MIN_NOTE_BODY) {
    throw new Error(`bodyMarkdown 需至少 ${MIN_NOTE_BODY} 字（当前 ${[...body].length}）——请按阅读框架写足再升级`)
  }
  const takeaway = patch.takeaway.map((t) => String(t).trim()).filter((t) => t.length > 0)
  if (takeaway.length === 0) throw new Error('升级为深读笔记至少要有 1 条 takeaway')

  const context = patch.context?.trim() || target.context
  const updated: ReadingEntry = {
    ...target,
    kind: 'note',
    ...(context ? { context } : {}),
    bodyMarkdown: body,
    takeaway,
    revisit: patch.revisit !== undefined ? normalizeRevisit(patch.revisit) : (target.revisit ?? []),
    updatedAt: new Date().toISOString(),
  }
  atomicWrite(file, rows.map((e) => (e.id === id ? updated : e)).map((e) => JSON.stringify(e)).join('\n') + '\n')
  writeObjectCard(entryObjectKey(updated))
  refreshHub(updated.subject.repo)
  refreshMOC()
  return updated
}

/**
 * Add structured external vault links to ONE event (dedupe, cap MAX_LINKS),
 * then rebuild that event's object card. Body text is untouched; links render
 * into the card's "关联 vault 笔记" section.
 */
export function addLinks(id: string, targets: readonly unknown[]): ReadingEntry {
  const root = ensureStore()
  const file = libraryFile(root)
  if (!existsSync(file)) throw new Error('档案为空，找不到要补链的记录')
  const rows = readEntries()
  const target = rows.find((e) => e.id === id)
  if (!target) throw new Error(`档案里没有 id=${id} 的记录`)
  const fresh = normalizeLinks(targets)
  if (fresh.length === 0) throw new Error('links 至少给一个要关联的笔记名')
  const merged = [...new Set([...(target.links ?? []), ...fresh])]
  if (merged.length > MAX_LINKS) throw new Error(`links 最多 ${MAX_LINKS} 个（当前追加后会到 ${merged.length}）`)
  const updated: ReadingEntry = { ...target, links: merged, updatedAt: new Date().toISOString() }
  atomicWrite(file, rows.map((e) => (e.id === id ? updated : e)).map((e) => JSON.stringify(e)).join('\n') + '\n')
  writeObjectCard(entryObjectKey(updated))
  refreshHub(updated.subject.repo)
  refreshMOC()
  return updated
}

/** Delete one event; rebuild its object card (or remove it) + hub + MOC. */
export function deleteEntry(id: string): boolean {
  const root = dataRoot()
  const file = libraryFile(root)
  if (!existsSync(file)) return false
  const before = readEntries()
  const removed = before.find((e) => e.id === id)
  if (!removed) return false
  const after = before.filter((e) => e.id !== id)
  atomicWrite(file, after.map((e) => JSON.stringify(e)).join('\n') + (after.length > 0 ? '\n' : ''))
  const key = entryObjectKey(removed)
  const survivors = after.filter((e) => entryObjectKey(e) === key)
  const noteFile = removed.noteFile
  if (survivors.length > 0) {
    writeObjectCard(key)
  } else if (noteFile) {
    const card = join(root, 'notes', `${noteFile}.md`)
    if (existsSync(card)) rmSync(card, { force: true })
  }
  refreshHub(removed.subject.repo)
  refreshMOC()
  return true
}

// ---------------------------------------------------------------------------
// Object card projection (notes/<noteFile>.md)
// ---------------------------------------------------------------------------

/** Path of one object's card file. */
export function objectCardPath(key: string): string {
  const rows = groupByObject(readEntries()).get(key) ?? []
  const name = rows.length > 0 ? (rows.find((e) => e.noteFile)?.noteFile ?? objectFileName(rows, readEntries())) : undefined
  return name ? join(dataRoot(), 'notes', `${name}.md`) : join(dataRoot(), 'notes', 'unresolved.md')
}

/** Path of the card that a specific event row belongs to. */
export function noteFilePath(e: ReadingEntry): string {
  return join(dataRoot(), 'notes', `${e.noteFile ?? e.id}.md`)
}

function yamlLine(value: string | readonly string[] | undefined): string {
  if (value === undefined) return ''
  return JSON.stringify(Array.isArray(value) ? [...value] : value)
}

/** Rebuild the card of one object from its events (atomic). */
export function writeObjectCard(key: string): string {
  const root = ensureStore()
  const events = groupByObject(readEntries()).get(key)
  if (!events || events.length === 0) return join(root, 'notes', 'gone.md')
  const noteFile = anchorOf(events).noteFile ?? objectFileName(events, readEntries())
  const file = join(root, 'notes', `${noteFile}.md`)
  atomicWrite(file, renderObjectCard(events, key, noteFile))
  return file
}

/**
 * Pure projection of an object's events into card Markdown. Split out of
 * writeObjectCard so the SAME renderer can replay a HISTORICAL subset of events
 * (read_history): the card as it would have looked after the Nth read is exactly
 * this function applied to the events known at that time.
 *
 * Every timeline entry carries its own coordinate + record instant, so the card
 * is a citation chain: which read, against which ref, produced which paragraph.
 */
export function renderObjectCard(
  allEvents: readonly ReadingEntry[],
  key: string,
  noteFile: string,
): string {
  const events = [...allEvents]
  if (events.length === 0) return ''
  const anchor = anchorOf(events)
  const newest = newestOf(events)
  const subject = subjectOfKey(key)
  const tags = [...new Set(events.flatMap((e) => e.tags))]
  const timelines = [...events].sort((a, b) => b.readAt.localeCompare(a.readAt))

  const fm = [
    '---',
    `kind: ${yamlLine('object')}`,
    `noteFile: ${yamlLine(noteFile)}`,
    `readCount: ${events.length}`,
    `firstReadAt: ${yamlLine(anchor.readAt)}`,
    `lastReadAt: ${yamlLine(newest.readAt)}`,
    `title: ${yamlLine(entryTitle(anchor))}`,
    `repo: ${yamlLine(subject.repo)}`,
    ...(subject.path ? [`path: ${yamlLine(subject.path)}`] : []),
    ...(subject.symbol ? [`symbol: ${yamlLine(subject.symbol)}`] : []),
    `tags: ${yamlLine(tags.length > 0 ? tags : undefined) ?? '[]'}`,
    '---',
  ].join('\n')

  const body: string[] = []
  body.push(`# ${entryTitle(anchor)}`)
  body.push('')
  body.push(`> 阅读对象 · ${subjectLabel(subject)}`)
  body.push(`> 读过 ${events.length} 次 · ${anchor.readAt.slice(0, 10)} ~ ${newest.readAt.slice(0, 10)}`)
  body.push('')
  body.push('## 阅读时间线（新 → 旧）')
  body.push('')
  for (const e of timelines) {
    body.push(`### ${e.readAt.slice(0, 10)} ${entryKindText(e.kind)} · id ${e.id}`)
    // Provenance line: which coordinates + which ref this paragraph came from.
    body.push(`> 出处：${subjectLabel(e.subject)}${e.subject.ref ? ` @ ${e.subject.ref}` : ''} · 记录于 ${e.readAt}`)
    if (e.context) body.push(`> **为什么读到这**：${e.context}`)
    body.push('')
    if (e.kind === 'capture') {
      body.push(e.note ?? '')
    } else {
      body.push(e.bodyMarkdown ?? '')
    }
    if (e.takeaway.length > 0) {
      body.push('')
      body.push(`**本条提炼**（${e.readAt.slice(0, 10)}）：`)
      for (const t of e.takeaway) body.push(`- ${t}`)
    }
    body.push('')
  }
  const merged = [...new Set(events.flatMap((e) => e.takeaway))]
  if (merged.length > 0) {
    body.push('## 全部提炼要点（去重合并）')
    body.push('')
    for (const t of merged) body.push(`- ${t}`)
    body.push('')
  }
  // Revisit questions: the retrieval-practice side of the archive. Merged across
  // events (newest first) and capped, so the card ends with something to THINK
  // about rather than something to re-read.
  const revisit = [
    ...new Set([...timelines].flatMap((e) => e.revisit ?? [])),
  ].slice(0, MAX_REVISIT)
  if (revisit.length > 0) {
    body.push('## 回访问题（下次重想这几条）')
    body.push('')
    for (const q of revisit) body.push(`- ${q}`)
    body.push('')
  }
  // "关联 vault 笔记" section: structured links + external wikilinks the model
  // wrote in bodies. Archive-internal refs use notes/ or hub/ prefixes.
  const externalLinks = collectExternalLinks(events)
  const linked = [...new Set([...events.flatMap((e) => e.links ?? []), ...externalLinks].map((l) => l.replace(/\[\[|\]\]/gu, '').trim()).filter(Boolean))]
  if (linked.length > 0) {
    body.push('## 关联 vault 笔记')
    body.push('')
    for (const link of linked) body.push(`- [[${link}]]`)
    body.push('')
  }
  const related = relatedObjectsSection(key)
  if (related.length > 0) {
    body.push('## 同仓其他对象')
    body.push('')
    body.push(related)
    body.push('')
  }

  // Callers (writeObjectCard / read_history) decide where this text goes.
  return `${fm}\n\n${body.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`
}
/** Links to OTHER object cards in the same repo (not self). */
function relatedObjectsSection(selfKey: string): string {
  const rows = readEntries()
  const self = rows.find((e) => entryObjectKey(e) === selfKey)
  if (!self) return ''
  const byObj = groupByObject(rows.filter((e) => e.subject.repo === self.subject.repo))
  const lines: string[] = []
  for (const [key, events] of byObj) {
    if (key === selfKey) continue
    const a = anchorOf(events)
    const nf = a.noteFile
    if (!nf) continue
    const newest = newestOf(events)
    lines.push(`- [[notes/${nf}|${entryTitle(a)}]] ${events.length} 次 · 最近 ${newest.readAt.slice(0, 10)}`)
  }
  return [...lines].sort().join('\n')
}

/**
 * Collect wikilinks the model wrote into event notes/bodies that point OUTSIDE
 * the plugin archive. Archive-internal refs are written as `[[notes/…]]` /
 * `[[hub/…]]`, so any other `[[Name]]` (or `[[path/Name]]`) is an external
 * link worth surfacing. Deduped, preserving first-seen order.
 */
function collectExternalLinks(events: ReadingEntry[]): string[] {
  const out: string[] = []
  const seen = new Set<string>()
  const PLACEHOLDERS = new Set(['链接', '链接名', '笔记名', '…'])
  for (const e of events) {
    const text = [e.note, e.context, e.bodyMarkdown, ...e.takeaway].filter((s): s is string => Boolean(s)).join('\n')
    for (const m of text.matchAll(/\[\[([^\]|]+)(?:\|[^\]]+)?\]\]/gu)) {
      // A body may already contain the literal [[Name]]; strip stray brackets.
      const target = m[1]!.replace(/\[\[|\]\]/gu, '').trim()
      if (!target) continue
      if (target.startsWith('notes/') || target.startsWith('hub/')) continue
      if (PLACEHOLDERS.has(target)) continue
      if (seen.has(target)) continue
      seen.add(target)
      out.push(target)
    }
  }
  return out
}

// ---------------------------------------------------------------------------
// Repo hub (hub/<slug>.md) & MOC
// ---------------------------------------------------------------------------

/** File-system & wikilink-safe slug of a repo identifier (keeps [a-z0-9._-]). */
export function hubSlug(repo: string): string {
  const cleaned = repo
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
  if (cleaned.length >= 3) return cleaned
  // All-CJK or otherwise unslugifiable repo: keep it unique via a short hash.
  return `repo-${createHash('sha1').update(repo).digest('hex').slice(0, 8)}`
}

export function hubPath(repo: string): string {
  return join(dataRoot(), 'hub', `${hubSlug(repo)}.md`)
}

/** Rebuild the hub page of one repo: one line per object card (atomic). */
export function refreshHub(repo: string): string {
  const root = ensureStore()
  const byObj = groupByObject(readEntries().filter((e) => e.subject.repo === repo))
  const file = join(root, 'hub', `${hubSlug(repo)}.md`)
  if (byObj.size === 0) {
    if (existsSync(file)) rmSync(file, { force: true })
    return file
  }
  const objects = [...byObj.entries()]
    .map(([key, events]) => ({ key, events, anchor: anchorOf(events), newest: newestOf(events) }))
    .sort((a, b) => b.newest.readAt.localeCompare(a.newest.readAt))
  const totalEvents = objects.reduce((n, o) => n + o.events.length, 0)
  const lines = [
    `# ${repo} · 源码阅读对象`,
    '',
    `共 ${objects.length} 个对象 · ${totalEvents} 次阅读 · 最近 ${objects[0]!.newest.readAt.slice(0, 10)}`,
    '',
    '## 对象（新 → 旧）',
    '',
  ]
  for (const o of objects) {
    if (!o.anchor.noteFile) continue
    lines.push(
      `- [[notes/${o.anchor.noteFile}|${entryTitle(o.anchor)}]] ${o.events.length} 次 · 最近 ${o.newest.readAt.slice(0, 10)} · ${entryKindText(o.newest.kind)}`,
    )
  }
  atomicWrite(file, lines.join('\n') + '\n')
  return file
}

interface RepoAgg {
  readonly repo: string
  readonly objects: number
  readonly events: number
  readonly latest: string
}

/** Per-repo aggregate over current events. */
function aggregateRepos(): RepoAgg[] {
  const byRepo = new Map<string, ReadingEntry[]>()
  for (const e of readEntries()) {
    const arr = byRepo.get(e.subject.repo) ?? []
    arr.push(e)
    byRepo.set(e.subject.repo, arr)
  }
  return [...byRepo.entries()]
    .map(([repo, events]) => ({
      repo,
      objects: groupByObject(events).size,
      events: events.length,
      latest: newestOf(events).readAt,
    }))
    .sort((a, b) => b.latest.localeCompare(a.latest))
}

/** Rebuild MOC.md from current events (atomic). */
export function refreshMOC(): string {
  const root = ensureStore()
  const rows = readEntries()
  const file = join(root, 'MOC.md')
  if (rows.length === 0) {
    const placeholder = [
      `# 源码阅读档案 · MOC`,
      '',
      '> 数据根：' + root,
      '> 还没有阅读记录。说"把刚才读到的记一下"，或用 `/codevault` 查看用法。',
      '',
    ].join('\n')
    atomicWrite(file, placeholder)
    return file
  }
  const repos = aggregateRepos()
  const objects = [...groupByObject(rows).entries()]
    .map(([key, events]) => ({ key, events, anchor: anchorOf(events), newest: newestOf(events) }))
    .sort((a, b) => b.newest.readAt.localeCompare(a.newest.readAt))
  const lines = [
    `# 源码阅读档案 · MOC`,
    '',
    `共 ${rows.length} 次阅读 · ${objects.length} 个对象 · 数据根：${root}`,
    '',
    '## 仓库',
    '',
  ]
  for (const r of repos) {
    lines.push(`- [[hub/${hubSlug(r.repo)}|${r.repo}]] — ${r.objects} 个对象 / ${r.events} 次阅读 · 最近 ${r.latest.slice(0, 10)}`)
  }
  lines.push('', '## 最近阅读对象', '')
  for (const o of objects.slice(0, 12)) {
    if (!o.anchor.noteFile) continue
    lines.push(`- [[notes/${o.anchor.noteFile}|${entryTitle(o.anchor)}]] ${o.events.length} 次 · 最近 ${o.newest.readAt.slice(0, 10)}`)
  }
  atomicWrite(file, lines.join('\n') + '\n')
  return file
}

// ---------------------------------------------------------------------------
// Migration: V1 event-cards -> V2 object cards (idempotent)
// ---------------------------------------------------------------------------

/**
 * One-time migration of archives written as V1 event-cards (rows with their
 * own noteFile/title) into V2 object cards. Each object's events must share ONE
 * noteFile; the anchor's existing name wins, others are renamed/reconciled.
 * Safe to run on every load: objects that already share a name are skipped.
 * @returns how many objects were (re)conciled.
 */
export function migrateLegacyNoteFiles(): number {
  const root = ensureStore()
  const rows = readEntries()
  if (rows.length === 0) return 0
  const byObj = groupByObject(rows)
  let reconciled = 0

  // Decide one noteFile per object.
  const decision = new Map<string, string>()
  const used = new Set(rows.map((e) => e.noteFile).filter((f): f is string => Boolean(f)))
  for (const [key, events] of byObj) {
    const anchor = anchorOf(events)
    const names = new Set(events.map((e) => e.noteFile).filter((f): f is string => Boolean(f)))
    if (names.size <= 1 && anchor.noteFile) continue // already consistent
    const existingName = events.find((e) => e.noteFile && e.noteFile !== anchor.id)?.noteFile
    let name = existingName ?? anchor.noteFile
    if (!name || name === anchor.id || [...used].includes(name)) {
      const base = cardFileName(objectTitle(events))
      name = base
      let i = 2
      while (used.has(name)) {
        name = `${base}-${i}`
        i += 1
      }
    }
    used.add(name)
    decision.set(key, name)
    reconciled += 1
  }
  if (reconciled === 0) {
    // Even with no rename needed, V1 cards must be re-projected into the V2
    // object-card layout (timeline + merged takeaways) on first load.
    for (const key of byObj.keys()) writeObjectCard(key)
    for (const repo of new Set(rows.map((e) => e.subject.repo))) refreshHub(repo)
    refreshMOC()
    return 0
  }

  // Rename old per-event cards into the object card name.
  const notesDir = join(root, 'notes')
  const next = rows.map((e) => {
    const key = entryObjectKey(e)
    const target = decision.get(key)
    if (!target || e.noteFile === target) return e
    const old = join(notesDir, `${e.noteFile ?? e.id}.md`)
    const fresh = join(notesDir, `${target}.md`)
    if (existsSync(old) && !existsSync(fresh)) renameSync(old, fresh)
    else if (existsSync(old) && existsSync(fresh) && old !== fresh) rmSync(old, { force: true })
    return { ...e, noteFile: target }
  })
  atomicWrite(libraryFile(root), next.map((e) => JSON.stringify(e)).join('\n') + '\n')

  for (const key of byObj.keys()) writeObjectCard(key)
  for (const repo of new Set(next.map((e) => e.subject.repo))) refreshHub(repo)
  refreshMOC()
  return reconciled
}

// ---------------------------------------------------------------------------
// Queries (object-card view, deterministic, no I/O beyond readEntries)
// ---------------------------------------------------------------------------

export interface EntryFilter {
  readonly repo?: string
  readonly path?: string
  readonly symbol?: string
  readonly tag?: string
  readonly kind?: 'capture' | 'note'
  readonly since?: string
}

export interface EventRef {
  readonly id: string
  readonly kind: 'capture' | 'note'
  readonly readAt: string
  readonly context?: string
  readonly note?: string
  readonly takeaway: readonly string[]
  readonly noteFile: string
  /** Cheap one-line summary (never the full bodyMarkdown). */
  readonly summary: string
}

export interface ObjectSummary {
  readonly noteFile: string
  readonly title: string
  readonly repo: string
  readonly ref?: string
  readonly path?: string
  readonly symbol?: string
  readonly readCount: number
  readonly firstReadAt: string
  readonly lastReadAt: string
  readonly tags: readonly string[]
  readonly events: readonly EventRef[]
}

function summarizeEvent(e: ReadingEntry): EventRef {
  return {
    id: e.id,
    kind: e.kind,
    readAt: e.readAt,
    ...(e.context ? { context: e.context } : {}),
    ...(e.note ? { note: e.note } : {}),
    takeaway: e.takeaway,
    noteFile: e.noteFile ?? e.id,
    summary: clip(e.kind === 'capture' ? (e.note ?? '') : (e.takeaway[0] ?? e.note ?? ''), 160),
  }
}

function summarizeObject(events: ReadingEntry[]): ObjectSummary {
  const anchor = anchorOf(events)
  const newest = newestOf(events)
  const subject = subjectOfKey(entryObjectKey(anchor))
  return {
    noteFile: anchor.noteFile ?? anchor.id,
    title: entryTitle(anchor),
    repo: subject.repo,
    ...(subject.path ? { path: subject.path } : {}),
    ...(subject.symbol ? { symbol: subject.symbol } : {}),
    readCount: events.length,
    firstReadAt: anchor.readAt,
    lastReadAt: newest.readAt,
    tags: [...new Set(events.flatMap((e) => e.tags))],
    events: [...events].sort((a, b) => b.readAt.localeCompare(a.readAt)).map(summarizeEvent),
  }
}

function objectMatches(events: ReadingEntry[], f: EntryFilter): boolean {
  const subject = subjectOfKey(entryObjectKey(events[0]!))
  if (f.repo && subject.repo.toLowerCase() !== f.repo.trim().toLowerCase()) return false
  if (f.path && !(subject.path ?? '').toLowerCase().includes(f.path.trim().toLowerCase())) return false
  if (f.symbol && !(subject.symbol ?? '').toLowerCase().includes(f.symbol.trim().toLowerCase())) return false
  if (f.tag && !events.some((e) => e.tags.includes(f.tag!.trim().toLowerCase()))) return false
  if (f.kind && !events.some((e) => e.kind === f.kind)) return false
  if (f.since) {
    const latest = newestOf(events).readAt.slice(0, 10)
    if (latest < f.since) return false
  }
  return true
}

export interface QueryResult {
  readonly total: number
  readonly objects: readonly ObjectSummary[]
}

/** Newest-first object view filtered across events; limit clamps 1..200. */
export function queryEntries(filter: EntryFilter, limit = 50): QueryResult {
  const safeLimit = Math.min(Math.max(1, Math.floor(limit) || 50), 200)
  const hits = [...groupByObject(readEntries()).values()]
    .filter((events) => objectMatches(events, filter))
    .sort((a, b) => newestOf(b).readAt.localeCompare(newestOf(a).readAt))
  return { total: hits.length, objects: hits.slice(0, safeLimit).map(summarizeObject) }
}

/** Recent object snapshot across all repos (days optional). */
export function recentEntries(days?: number, limit = 8): QueryResult {
  const safeLimit = Math.min(Math.max(1, Math.floor(limit) || 8), 50)
  const cutoff = days !== undefined ? new Date(Date.now() - days * 86_400_000).toISOString() : undefined
  const hits = [...groupByObject(readEntries()).values()]
    .filter((events) => (cutoff ? newestOf(events).readAt >= cutoff : true))
    .sort((a, b) => newestOf(b).readAt.localeCompare(newestOf(a).readAt))
  return { total: hits.length, objects: hits.slice(0, safeLimit).map(summarizeObject) }
}

export interface ArchiveStats {
  readonly total: number
  readonly objects: number
  readonly repos: number
  readonly captures: number
  readonly notes: number
}

export function archiveStats(): ArchiveStats {
  const rows = readEntries()
  return {
    total: rows.length,
    objects: groupByObject(rows).size,
    repos: aggregateRepos().length,
    captures: rows.filter((e) => e.kind === 'capture').length,
    notes: rows.filter((e) => e.kind === 'note').length,
  }
}

// ---------------------------------------------------------------------------
// Tag vocabulary (tag discipline: suggest only what already exists)
// ---------------------------------------------------------------------------

/** Every tag currently used anywhere in the archive, sorted — the vocabulary. */
export function vocabularyTags(): string[] {
  return [...new Set(readEntries().flatMap((e) => e.tags ?? []))].sort()
}

/** Tags already attached to one object (so re-tagging never drops them). */
export function tagsOfObjectKey(key: string): string[] {
  const events = groupByObject(readEntries()).get(key) ?? []
  return [...new Set(events.flatMap((e) => e.tags ?? []))]
}

// ---------------------------------------------------------------------------
// History replay (read_history): the card AS IT WAS after the Nth read
// ---------------------------------------------------------------------------

export interface HistoryLocator {
  /** Event id of any event belonging to the object. */
  readonly id?: string
  /** Card file name (no `.md`) of the object. */
  readonly noteFile?: string
  /** Coordinate locator (repo required; path/symbol narrow it). */
  readonly repo?: string
  readonly path?: string
  readonly symbol?: string
}

export interface HistoryBoundary {
  /** Replay only events recorded at/before this instant (YYYY-MM-DD or ISO). */
  readonly at?: string
  /** Replay only the first N reads (1-based). */
  readonly index?: number
}

export interface HistoryEventRef {
  readonly id: string
  readonly kind: EntryKind
  readonly readAt: string
  readonly title: string
  readonly ref?: string
}

export interface HistoryResult {
  readonly found: boolean
  readonly noteFile: string
  readonly title: string
  readonly subject: ReadingSubject | undefined
  readonly totalEvents: number
  readonly shownEvents: number
  /** ISO instant of the last replayed event ('' when nothing was replayed). */
  readonly asOf: string
  readonly events: readonly HistoryEventRef[]
  /** The card projection of the replayed subset ('' when not found/empty). */
  readonly markdown: string
}

function emptyHistory(): HistoryResult {
  return {
    found: false,
    noteFile: '',
    title: '',
    subject: undefined,
    totalEvents: 0,
    shownEvents: 0,
    asOf: '',
    events: [],
    markdown: '',
  }
}

/** Resolve the object a locator points at (id > noteFile > coordinate). */
function resolveObject(locator: HistoryLocator): { key: string; events: ReadingEntry[] } | undefined {
  const rows = readEntries()
  const byObj = groupByObject(rows)
  if (locator.id) {
    const hit = rows.find((e) => e.id === locator.id)
    if (!hit) return undefined
    const key = entryObjectKey(hit)
    return { key, events: byObj.get(key) ?? [hit] }
  }
  if (locator.noteFile) {
    const want = locator.noteFile.trim()
    const hit = rows.find((e) => (e.noteFile ?? e.id) === want)
    if (!hit) return undefined
    const key = entryObjectKey(hit)
    return { key, events: byObj.get(key) ?? [hit] }
  }
  if (locator.repo?.trim()) {
    const want = locator.repo.trim().toLowerCase()
    const path = locator.path?.trim().toLowerCase()
    const symbol = locator.symbol?.trim().toLowerCase()
    for (const [key, events] of byObj) {
      const subject = subjectOfKey(key)
      if (subject.repo.toLowerCase() !== want) continue
      if (path && !(subject.path ?? '').toLowerCase().includes(path)) continue
      if (symbol && !(subject.symbol ?? '').toLowerCase().includes(symbol)) continue
      return { key, events }
    }
  }
  return undefined
}

/**
 * Replay an object card to a past point: the events known up to `at` / after the
 * first `index` reads, rendered through the SAME projection the live card uses.
 * This is what makes "how did I understand this last time?" answerable — the
 * append-only log IS the version history, this only exposes it.
 */
export function objectHistory(locator: HistoryLocator, boundary: HistoryBoundary = {}): HistoryResult {
  const resolved = resolveObject(locator)
  if (!resolved) return emptyHistory()
  const ordered = [...resolved.events].sort((a, b) => a.readAt.localeCompare(b.readAt))
  let cut = ordered
  if (boundary.at?.trim()) {
    const raw = boundary.at.trim()
    const iso = /^\d{4}-\d{2}-\d{2}$/u.test(raw) ? `${raw}T23:59:59.999Z` : raw
    const limit = Date.parse(iso)
    if (Number.isNaN(limit)) throw new Error('at 需为 YYYY-MM-DD 或 ISO 时间字符串')
    cut = cut.filter((e) => Date.parse(e.readAt) <= limit)
  }
  if (boundary.index !== undefined) {
    const n = Math.floor(boundary.index)
    if (!Number.isFinite(n) || n < 1) throw new Error('index 需为 ≥1 的整数（第几次阅读之后）')
    cut = cut.slice(0, n)
  }
  const noteFile = anchorOf(resolved.events).noteFile ?? objectFileName(resolved.events, readEntries())
  const events: HistoryEventRef[] = cut.map((e) => ({
    id: e.id,
    kind: e.kind,
    readAt: e.readAt,
    title: entryTitle(e),
    ...(e.subject.ref ? { ref: e.subject.ref } : {}),
  }))
  const last = cut[cut.length - 1]
  return {
    found: true,
    noteFile,
    title: objectTitle(resolved.events),
    subject: subjectOfKey(resolved.key),
    totalEvents: ordered.length,
    shownEvents: cut.length,
    asOf: last ? last.readAt : '',
    events,
    markdown: cut.length > 0 ? renderObjectCard(cut, resolved.key, noteFile) : '',
  }
}
"
    },
    {
      "path": "src/tools.ts",
      "content": "/**
 * Model-facing tools of dsh-codevault.
 *
 * Division of labour (by design, same as dsh-listening):
 *  - The MODEL does the writing: it thinks against the code-reading skill and
 *    hands the plugin structured subject coordinates + finished prose.
 *  - The TOOLS only validate, persist, aggregate and refresh the hub/MOC.
 *    None of them "creates content", which keeps them deterministic and small.
 */

import { defineTool } from '@deepseek-ai/dsh-tools'
import {
  EntryKind,
  MIN_NOTE_BODY,
  ReadingSubject,
  applyTagPolicy,
  buildEntry,
  entryKindText,
  entryObjectKey,
  entryTitle,
  objectKey,
  subjectLabel,
} from './domain.js'
import {
  addLinks,
  commitEntry,
  deleteEntry,
  expandEntry,
  groupByObject,
  noteFilePath,
  objectHistory,
  queryEntries,
  readEntries,
  recentEntries,
  tagsOfObjectKey,
  vocabularyTags,
} from './store.js'
import { readVaultNote, searchVault, suggestVault, vaultRoot } from './vault.js'

/**
 * Post-write PROPOSALS (never auto-applied): what the archive thinks might be
 * worth doing next, offered to the user for confirmation —
 *  - suggestUpgrade: an object read several times that still only has captures;
 *  - relatedNotes: earlier vault notes that look related (vaultDir configured).
 * The tool layer never links or expands on its own; the user (or the user's
 * explicit instruction) decides.
 */
interface Proposal {
  readonly readCount: number
  readonly suggestUpgrade: boolean
  readonly relatedNotes: readonly { readonly basename: string; readonly path: string }[]
}

function buildProposal(subject: ReadingSubject, tags: readonly string[], kind: EntryKind): Proposal {
  const key = objectKey(subject)
  const events = groupByObject(readEntries()).get(key) ?? []
  const readCount = events.length
  const hasNote = events.some((e) => e.kind === 'note')
  const suggestUpgrade = kind === 'capture' && !hasNote && readCount >= 2
  const relatedNotes: { basename: string; path: string }[] = []
  if (vaultRoot() && tags.length > 0) {
    try {
      for (const s of suggestVault({ words: [...tags], limit: 3 }).suggestions) {
        relatedNotes.push({ basename: s.basename, path: s.path })
      }
    } catch {
      // Related-note discovery is optional context; never block a write.
    }
  }
  return { readCount, suggestUpgrade, relatedNotes }
}

/** Render at most `max` characters of card Markdown for a tool result. */
function clipMarkdown(markdown: string, max = 8000): { text: string; truncated: boolean } {
  if ([...markdown].length <= max) return { text: markdown, truncated: false }
  return { text: `${[...markdown].slice(0, max).join('')}\n\n…（卡片较长，已截断）`, truncated: true }
}

/** Shared param: revisit questions (retrieval prompts stored with the event). */
const REVISIT_PARAM = {
  type: 'array',
  items: { type: 'string' },
